102	// DeleteNodes deletes nodes from this node group. Error is returned
103	// either on failure or if the given node doesn't belong to this node
104	// group. This function should wait until node group size is updated.
105	// Implementation required.
106	func (ng *nodegroup) DeleteNodes(ctx context.Context, nodes []*corev1.Node) error {
107		ng.machineController.accessLock.Lock()
108		defer ng.machineController.accessLock.Unlock()
109	
110		replicas, err := ng.scalableResource.Replicas()
111		if err != nil {
112			return err
113		}
114	
115		// if we are at minSize already we fail early.
116		if replicas <= ng.MinSize(context.TODO()) {
117			return fmt.Errorf("min size reached, nodes will not be deleted")
118		}
119	
120		// Step 1: Verify all nodes belong to this node group.
121		for _, node := range nodes {
122			actualNodeGroup, err := ng.machineController.nodeGroupForNode(node)
123			if err != nil {
124				if k8serrors.IsNotFound(err) {
125					klog.Warningf("Node group not found for node %q, skipping verification: %v", node.Spec.ProviderID, err)
126					continue
127				}
128				return err
129			}
130			if actualNodeGroup == nil {
131				return fmt.Errorf("no node group found for node %q", node.Spec.ProviderID)
132			}
133	
134			if actualNodeGroup.Id() != ng.Id() {
135				return fmt.Errorf("node %q doesn't belong to node group %q", node.Spec.ProviderID, ng.Id())
136			}
137		}
138	
139		// Step 2: if deleting len(nodes) would make the replica count
140		// < minSize, then the request to delete that many nodes is bogus
141		// and we fail fast.
142		if replicas-len(nodes) < ng.MinSize(context.TODO()) {
143			return fmt.Errorf("unable to delete %d machines in %q, machine replicas are %d, minSize is %d", len(nodes), ng.Id(), replicas, ng.MinSize(context.TODO()))
144		}
145	
146		// Step 3: when a backing Machine exists, mark it as a deletion candidate
147		// and decrease the replica count by 1. For MachinePool-backed node groups,
148		// if no per-node Machine can be resolved, fall back to replica decrement
149		// after verifying the node belongs to the MachinePool providerID list.
150		for _, node := range nodes {
151			nodeGroup, err := ng.machineController.nodeGroupForNode(node)
152			if err != nil {
153				if k8serrors.IsNotFound(err) {
154					klog.Warningf("Node group not found for node %q, skipping deletion: %v", node.Spec.ProviderID, err)
155					continue
156				}
157				return err
158			}
159	
160			machine, err := ng.machineController.findMachineByProviderID(normalizedProviderString(node.Spec.ProviderID))
161			if err != nil && !k8serrors.IsNotFound(err) {
162				return err
163			}
164	
165			if machine == nil {
166				// Fallback for MachinePool-based providers where no per-node Machine
167				// objects exist. In that case, allow scale-down by decreasing replicas,
168				// but only if the node providerID is explicitly present in the
169				// MachinePool providerIDList.
170				if nodeGroup.scalableResource.Kind() == machinePoolKind {
171					providerIDs, err := nodeGroup.scalableResource.ProviderIDs()
172					if err != nil {
173						return err
174					}
175	
176					nodeProviderID := normalizedProviderString(node.Spec.ProviderID)
177					found := false
178					for _, id := range providerIDs {
179						if normalizedProviderString(id) == nodeProviderID {
180							found = true
181							break
182						}
183					}
184	
185					if !found {
186						return fmt.Errorf("node %q is not present in MachinePool providerIDList for nodegroup %q", node.Spec.ProviderID, nodeGroup.Id())
187					}
188	
189					klog.Warningf("No Machine found for node %q in MachinePool %q, falling back to replica decrement only", node.Spec.ProviderID, nodeGroup.Id())
190	
191					if err := nodeGroup.scalableResource.SetSize(replicas - 1); err != nil {
192						return err
193					}
194	
195					replicas--
196					continue
197				}
198	
199				return fmt.Errorf("unknown machine for node %q", node.Spec.ProviderID)
200			}
201	
202			machine = machine.DeepCopy()
203	
204			if !machine.GetDeletionTimestamp().IsZero() {
205				// The machine for this node is already being deleted
206				continue
207			}
208	
209			if err := nodeGroup.scalableResource.MarkMachineForDeletion(machine); err != nil {
210				return err
211			}
212	
213			if err := nodeGroup.scalableResource.SetSize(replicas - 1); err != nil {
214				_ = nodeGroup.scalableResource.UnmarkMachineForDeletion(machine)
215				return err
216			}
217	
218			replicas--
219		}
220	
221		return nil
222	}
