602		if err != nil {
603			return nil, err
604		}
605	
606		// Ensure that if the nodegroup has 0 replicas it is capable
607		// of scaling before adding it.
608		if found && replicas == 0 && !scalableResource.CanScaleFromZero() {
609			return nil, nil
610		}
611	
612		// Ensure the node group would have the capacity to scale
613		// allow MinSize = 0
614		// allow MaxSize = MinSize
615		// don't allow MaxSize < MinSize
616		// don't allow MaxSize = MinSize = 0
617		if scalableResource.MaxSize()-scalableResource.MinSize() < 0 || scalableResource.MaxSize() == 0 {
